{
  "name": "feedback-insights",
  "private": true,
  "version": "1.0.0",
  "type": "module",
  "description": "AI Feedback-to-Action Assistant — an Experience.com dashboard panel that turns raw customer feedback into themes, actions, and filed Jira tickets.",
  "scripts": {
    "dev": "vite",
    "build": "vite build",
    "preview": "vite preview"
  },
  "dependencies": {
    "react": "^18.3.1",
    "react-dom": "^18.3.1"
  },
  "devDependencies": {
    "@vitejs/plugin-react": "^4.3.4",
    "vite": "^5.4.11"
  }
}

import { defineConfig } from 'vite'
import react from '@vitejs/plugin-react'
import fs from 'node:fs'
import path from 'node:path'

import { CLASSIFY_TOOL, CLASSIFY_PROMPT, PLAN_TOOL, PLAN_PROMPT } from './server/prompts.js'

// ---------------------------------------------------------------------------
// Model routing — rule 2 of the hackathon brief: match the model to the job.
//
//   Stage 1  classify 60 verbatims   -> Haiku 4.5. Extraction + labelling, no
//                                       hard reasoning, high token volume.
//   Stage 2  action plan + Jira      -> Sonnet 5. One call. Prioritisation,
//                                       impact/effort judgement and ticket
//                                       authoring is where reasoning earns it.
//   Opus                             -> deliberately never used here.
// ---------------------------------------------------------------------------
const CLASSIFY_MODEL = 'claude-haiku-4-5-20251001'
const PLAN_MODEL = 'claude-sonnet-5'

const ANTHROPIC_URL = 'https://api.anthropic.com/v1/messages'

function loadEnv() {
  // Read .env without a dependency. Vite's own loadEnv only exposes VITE_*.
  const file = path.resolve(process.cwd(), '.env')
  if (!fs.existsSync(file)) return
  for (const line of fs.readFileSync(file, 'utf8').split('\n')) {
    const m = line.match(/^\s*([A-Z0-9_]+)\s*=\s*(.*)\s*$/)
    if (m && !process.env[m[1]]) process.env[m[1]] = m[2].replace(/^["']|["']$/g, '')
  }
}

async function callClaude({ model, system, user, tool, maxTokens }) {
  const key = process.env.ANTHROPIC_API_KEY
  if (!key) {
    const err = new Error('ANTHROPIC_API_KEY not set')
    err.code = 'NO_KEY'
    throw err
  }

  const started = Date.now()
  const res = await fetch(ANTHROPIC_URL, {
    method: 'POST',
    headers: {
      'content-type': 'application/json',
      'x-api-key': key,
      'anthropic-version': '2023-06-01',
    },
    body: JSON.stringify({
      model,
      max_tokens: maxTokens,
      system,
      messages: [{ role: 'user', content: user }],
      tools: [tool],
      // Force the model through the schema so React renders the result directly
      // instead of us parsing prose and hoping.
      tool_choice: { type: 'tool', name: tool.name },
    }),
  })

  if (!res.ok) {
    const body = await res.text()
    const err = new Error(`Anthropic ${res.status}: ${body.slice(0, 400)}`)
    err.code = 'API_ERROR'
    throw err
  }

  const json = await res.json()
  const block = json.content?.find((c) => c.type === 'tool_use')
  if (!block) {
    const err = new Error('Model returned no tool_use block')
    err.code = 'API_ERROR'
    throw err
  }

  return {
    data: block.input,
    meta: {
      model,
      ms: Date.now() - started,
      inputTokens: json.usage?.input_tokens ?? 0,
      outputTokens: json.usage?.output_tokens ?? 0,
    },
  }
}

// Approximate published list prices (USD per 1M tokens), used only to show the
// cost delta of the routing decision in the UI.
const PRICES = {
  'claude-haiku-4-5-20251001': { in: 1.0, out: 5.0 },
  'claude-sonnet-5': { in: 3.0, out: 15.0 },
  'claude-opus-5': { in: 15.0, out: 75.0 },
}

function costOf(meta) {
  const p = PRICES[meta.model] ?? { in: 0, out: 0 }
  return (meta.inputTokens / 1e6) * p.in + (meta.outputTokens / 1e6) * p.out
}

function readBody(req) {
  return new Promise((resolve, reject) => {
    let raw = ''
    req.on('data', (c) => (raw += c))
    req.on('end', () => {
      try {
        resolve(JSON.parse(raw || '{}'))
      } catch (e) {
        reject(e)
      }
    })
    req.on('error', reject)
  })
}

function send(res, status, payload) {
  res.statusCode = status
  res.setHeader('content-type', 'application/json')
  res.end(JSON.stringify(payload))
}

function apiPlugin() {
  return {
    name: 'feedback-insights-api',
    configureServer(server) {
      loadEnv()

      server.middlewares.use('/api/health', (req, res) => {
        send(res, 200, {
          liveMode: Boolean(process.env.ANTHROPIC_API_KEY),
          classifyModel: CLASSIFY_MODEL,
          planModel: PLAN_MODEL,
        })
      })

      // Stage 1 — Haiku. Per-verbatim sentiment + theme tagging.
      server.middlewares.use('/api/analyze', async (req, res, next) => {
        if (req.method !== 'POST') return next()
        try {
          const { responses } = await readBody(req)
          const compact = responses.map((r) => ({ id: r.id, rating: r.rating, text: r.text }))
          const { data, meta } = await callClaude({
            model: CLASSIFY_MODEL,
            system: CLASSIFY_PROMPT,
            user: JSON.stringify(compact),
            tool: CLASSIFY_TOOL,
            maxTokens: 8000,
          })
          send(res, 200, { ...data, _meta: { ...meta, costUsd: costOf(meta) } })
        } catch (e) {
          send(res, e.code === 'NO_KEY' ? 503 : 500, { error: e.message, code: e.code || 'ERROR' })
        }
      })

      // Stage 2 — Sonnet. Action plan, product-issue detection, Jira ticket.
      server.middlewares.use('/api/action-plan', async (req, res, next) => {
        if (req.method !== 'POST') return next()
        try {
          const { analysis, evidence } = await readBody(req)
          const { data, meta } = await callClaude({
            model: PLAN_MODEL,
            system: PLAN_PROMPT,
            user: JSON.stringify({ analysis, evidence }),
            tool: PLAN_TOOL,
            maxTokens: 4000,
          })
          send(res, 200, { ...data, _meta: { ...meta, costUsd: costOf(meta) } })
        } catch (e) {
          send(res, e.code === 'NO_KEY' ? 503 : 500, { error: e.message, code: e.code || 'ERROR' })
        }
      })
    },
  }
}

export default defineConfig({
  plugins: [react(), apiPlugin()],
  server: { port: 5180 },
})

import { defineConfig } from 'vite'
import react from '@vitejs/plugin-react'
import fs from 'node:fs'
import path from 'node:path'

import { CLASSIFY_TOOL, CLASSIFY_PROMPT, PLAN_TOOL, PLAN_PROMPT } from './server/prompts.js'
import { CLASSIFY_MODEL, PLAN_MODEL, PRICES } from './server/models.js'

const ANTHROPIC_URL = 'https://api.anthropic.com/v1/messages'

function loadEnv() {
  // Read .env without a dependency — Vite's own loadEnv only exposes VITE_*,
  // and the API key must stay server-side.
  const file = path.resolve(process.cwd(), '.env')
  if (!fs.existsSync(file)) return
  for (const line of fs.readFileSync(file, 'utf8').split('\n')) {
    const m = line.match(/^\s*([A-Z0-9_]+)\s*=\s*(.*?)\s*$/)
    if (m && !process.env[m[1]]) process.env[m[1]] = m[2].replace(/^["']|["']$/g, '')
  }
}

async function callClaude({ model, system, user, tool, maxTokens }) {
  const key = process.env.ANTHROPIC_API_KEY
  if (!key) {
    const err = new Error('ANTHROPIC_API_KEY not set')
    err.code = 'NO_KEY'
    throw err
  }

  const started = Date.now()
  const res = await fetch(ANTHROPIC_URL, {
    method: 'POST',
    headers: {
      'content-type': 'application/json',
      'x-api-key': key,
      'anthropic-version': '2023-06-01',
    },
    body: JSON.stringify({
      model,
      max_tokens: maxTokens,
      system,
      messages: [{ role: 'user', content: user }],
      tools: [tool],
      // Force the model through the schema so React renders the result directly
      // instead of parsing prose and hoping.
      tool_choice: { type: 'tool', name: tool.name },
    }),
  })

  if (!res.ok) {
    const body = await res.text()
    const err = new Error(`Anthropic ${res.status}: ${body.slice(0, 300)}`)
    err.code = 'API_ERROR'
    throw err
  }

  const json = await res.json()
  const block = json.content?.find((c) => c.type === 'tool_use')
  if (!block) {
    const err = new Error('Model returned no tool_use block')
    err.code = 'API_ERROR'
    throw err
  }

  const meta = {
    model,
    ms: Date.now() - started,
    inputTokens: json.usage?.input_tokens ?? 0,
    outputTokens: json.usage?.output_tokens ?? 0,
  }
  const p = PRICES[model] ?? { in: 0, out: 0 }
  meta.costUsd = (meta.inputTokens / 1e6) * p.in + (meta.outputTokens / 1e6) * p.out

  return { data: block.input, meta }
}

function readBody(req) {
  return new Promise((resolve, reject) => {
    let raw = ''
    req.on('data', (c) => (raw += c))
    req.on('end', () => {
      try {
        resolve(JSON.parse(raw || '{}'))
      } catch (e) {
        reject(e)
      }
    })
    req.on('error', reject)
  })
}

function send(res, status, payload) {
  res.statusCode = status
  res.setHeader('content-type', 'application/json')
  res.end(JSON.stringify(payload))
}

function apiPlugin() {
  return {
    name: 'feedback-insights-api',
    configureServer(server) {
      loadEnv()

      server.middlewares.use('/api/health', (req, res) => {
        send(res, 200, {
          liveMode: Boolean(process.env.ANTHROPIC_API_KEY),
          classifyModel: CLASSIFY_MODEL,
          planModel: PLAN_MODEL,
        })
      })

      // Stage 1 — Haiku. Per-verbatim sentiment + theme tagging, batched.
      server.middlewares.use('/api/analyze', async (req, res, next) => {
        if (req.method !== 'POST') return next()
        try {
          const { responses } = await readBody(req)
          const compact = responses.map((r) => ({ id: r.id, rating: r.rating, text: r.text }))
          const { data, meta } = await callClaude({
            model: CLASSIFY_MODEL,
            system: CLASSIFY_PROMPT,
            user: JSON.stringify(compact),
            tool: CLASSIFY_TOOL,
            maxTokens: 8000,
          })
          send(res, 200, { ...data, _meta: meta })
        } catch (e) {
          send(res, e.code === 'NO_KEY' ? 503 : 500, { error: e.message, code: e.code || 'ERROR' })
        }
      })

      // Stage 2 — Sonnet. Action plan, product-issue detection, Jira ticket.
      server.middlewares.use('/api/action-plan', async (req, res, next) => {
        if (req.method !== 'POST') return next()
        try {
          const { analysis, evidence } = await readBody(req)
          const { data, meta } = await callClaude({
            model: PLAN_MODEL,
            system: PLAN_PROMPT,
            user: JSON.stringify({ analysis, evidence }),
            tool: PLAN_TOOL,
            maxTokens: 4000,
          })
          send(res, 200, { ...data, _meta: meta })
        } catch (e) {
          send(res, e.code === 'NO_KEY' ? 503 : 500, { error: e.message, code: e.code || 'ERROR' })
        }
      })
    },
  }
}

export default defineConfig({
  plugins: [react(), apiPlugin()],
  server: { port: 5180 },
})

// ---------------------------------------------------------------------------
// Model routing — hackathon rule 2: "Don't reach for Opus by default. Match the
// model to the job."
//
//   Stage 1 · classify 60 verbatims  -> Haiku 4.5
//     Labelling and extraction against a fixed schema. High token volume, no
//     hard reasoning. The cheapest model that can do it is the correct model.
//
//   Stage 2 · action plan + Jira     -> Sonnet 5
//     One call. Weighing impact against effort, deciding what is actually a
//     product defect versus a one-off complaint, and authoring a ticket an
//     engineer can pick up — this is the only step where reasoning earns cost.
//
//   Opus                             -> deliberately not used.
//     Nothing here needs it. Using it would triple cost for no measurable gain.
// ---------------------------------------------------------------------------

export const CLASSIFY_MODEL = 'claude-haiku-4-5-20251001'
export const PLAN_MODEL = 'claude-sonnet-5'

// Published list prices (USD per 1M tokens). Used only to show the cost of the
// routing decision in the UI — including what the naive all-Opus run would cost.
export const PRICES = {
  'claude-haiku-4-5-20251001': { in: 1.0, out: 5.0 },
  'claude-sonnet-5': { in: 3.0, out: 15.0 },
  'claude-opus-5': { in: 15.0, out: 75.0 },
}

export const OPUS_MODEL = 'claude-opus-5'

// ---------------------------------------------------------------------------
// The two production prompts. Both are forced through a tool schema so the
// model returns data the UI can render directly — no prose parsing.
// These are mirrored in prompt.md at the branch root for reuse.
// ---------------------------------------------------------------------------

// === STAGE 1 — Haiku · classify ============================================

export const CLASSIFY_PROMPT = `You are a customer-feedback analyst for Experience.com, an experience management platform used by loan officers, real estate agents, branch managers and team admins to collect reviews and survey responses from their own clients.

The feedback you are given is about the Experience.com platform itself, left by those business customers through in-app NPS surveys, in-app surveys and support tickets.

Your job is labelling, not advice. For every response you receive:

1. Assign exactly one sentiment: "positive", "neutral" or "negative".
   - Judge the words, not the star rating. A 5-star review that says "support was excellent but checkout was confusing" is mixed: classify the dominant tone, and still record the negative theme.
   - "neutral" means genuinely mixed or factual, not mildly positive.
2. Assign one or more themes from this fixed list. Never invent a theme name:
   - "Support"            help quality, responsiveness of the support team
   - "Fast Service"       speed — response times, turnaround, how quickly things happen
   - "Staff Friendliness" tone and manner of people, being looked after
   - "Pricing Confusion"  plan comparison, tiers, invoices, proration, unclear cost
   - "Checkout Issues"    upgrade/payment flow — errors, failures, unclear steps
   - "Reporting"          dashboards, exports, analytics
   - "Review Campaigns"   review requests, survey sends, response rates, profile pages
3. For each theme you assign, record the sentiment that theme carries in that specific response. A response can praise Support and criticise Checkout Issues at the same time.

Rules:
- Every input id must appear exactly once in your output.
- Do not summarise, do not recommend, do not editorialise. Labels only.
- If a response carries no identifiable theme, return an empty themes array.`

export const CLASSIFY_TOOL = {
  name: 'record_classifications',
  description: 'Record the sentiment and theme labels for every feedback response.',
  input_schema: {
    type: 'object',
    properties: {
      classifications: {
        type: 'array',
        description: 'One entry per input response, in the same order.',
        items: {
          type: 'object',
          properties: {
            id: { type: 'string', description: 'The response id exactly as given.' },
            sentiment: {
              type: 'string',
              enum: ['positive', 'neutral', 'negative'],
              description: 'Dominant sentiment of the response as a whole.',
            },
            themes: {
              type: 'array',
              description: 'Themes present in this response, with the sentiment each one carries.',
              items: {
                type: 'object',
                properties: {
                  name: {
                    type: 'string',
                    enum: [
                      'Support',
                      'Fast Service',
                      'Staff Friendliness',
                      'Pricing Confusion',
                      'Checkout Issues',
                      'Reporting',
                      'Review Campaigns',
                    ],
                  },
                  sentiment: { type: 'string', enum: ['positive', 'neutral', 'negative'] },
                },
                required: ['name', 'sentiment'],
              },
            },
          },
          required: ['id', 'sentiment', 'themes'],
        },
      },
    },
    required: ['classifications'],
  },
}

// === STAGE 2 — Sonnet · action plan + product issue + Jira ticket ==========

export const PLAN_PROMPT = `You are a senior product manager at Experience.com reviewing 30 days of customer feedback about the platform.

You receive: aggregate counts per theme with their sentiment split, and a set of verbatim quotes as evidence. You do not receive the raw dataset — reason only from what you are given.

Produce four things.

1. KEY INSIGHT — two or three sentences a VP can read in ten seconds. Name what customers value and what is costing them. Be concrete: reference the themes and the numbers you were given. No filler, no "customers have shared valuable feedback".

2. RECOMMENDED ACTIONS — three of them, ordered by priority. Each is a short imperative title plus one sentence of justification grounded in the evidence. Priority is "High", "Medium" or "Low".

3. ACTION PLAN — five rows. Each has an action, a priority, an expected impact and an effort estimate. Impact and effort are "High", "Medium" or "Low". Be honest about effort: a copy change is Low, a checkout flow rebuild is High. Order the plan so the best impact-to-effort trades come first.

4. PRODUCT ISSUE — the single strongest signal that this is a real product defect rather than scattered dissatisfaction. Judge it properly:
   - Only report an issue where multiple customers independently describe the same failure.
   - confidence is your genuine assessment (0-100) that engineering will find a real defect. Volume of complaints, consistency of description and specificity all raise it. Two vague grumbles do not make a 90.
   - Write a Jira ticket an engineer can pick up without asking questions: a specific title, a problem statement citing how many customers reported it, and 3-5 concrete acceptance criteria that state what "fixed" looks like.
   - suggestedPriority uses Jira conventions: P1 is revenue-blocking or broken for many, P2 is significant, P3 is minor.

Ground every claim in the evidence you were given. Do not invent numbers.`

export const PLAN_TOOL = {
  name: 'record_action_plan',
  description: 'Record the insight, recommendations, action plan and detected product issue.',
  input_schema: {
    type: 'object',
    properties: {
      keyInsight: {
        type: 'string',
        description: 'Two to three sentences naming what customers value and what is costing them.',
      },
      recommendations: {
        type: 'array',
        description: 'Exactly three recommended actions, highest priority first.',
        items: {
          type: 'object',
          properties: {
            title: { type: 'string', description: 'Short imperative title.' },
            detail: { type: 'string', description: 'One sentence of justification from the evidence.' },
            priority: { type: 'string', enum: ['High', 'Medium', 'Low'] },
          },
          required: ['title', 'detail', 'priority'],
        },
      },
      actionPlan: {
        type: 'array',
        description: 'Exactly five rows, best impact-to-effort trades first.',
        items: {
          type: 'object',
          properties: {
            action: { type: 'string' },
            priority: { type: 'string', enum: ['High', 'Medium', 'Low'] },
            impact: { type: 'string', enum: ['High', 'Medium', 'Low'] },
            effort: { type: 'string', enum: ['High', 'Medium', 'Low'] },
          },
          required: ['action', 'priority', 'impact', 'effort'],
        },
      },
      productIssue: {
        type: 'object',
        description: 'The strongest evidence-backed product defect signal.',
        properties: {
          theme: { type: 'string', description: 'Theme the issue sits under.' },
          evidenceCount: {
            type: 'integer',
            description: 'How many customers independently reported this.',
          },
          confidence: {
            type: 'integer',
            description: 'Genuine 0-100 confidence that engineering finds a real defect.',
          },
          summary: { type: 'string', description: 'One sentence stating the defect.' },
          jira: {
            type: 'object',
            properties: {
              title: { type: 'string' },
              problem: {
                type: 'string',
                description: 'Problem statement citing how many customers reported it.',
              },
              acceptanceCriteria: {
                type: 'array',
                items: { type: 'string' },
                description: 'Three to five concrete criteria describing what fixed looks like.',
              },
              suggestedPriority: { type: 'string', enum: ['P1', 'P2', 'P3'] },
              labels: { type: 'array', items: { type: 'string' } },
            },
            required: ['title', 'problem', 'acceptanceCriteria', 'suggestedPriority', 'labels'],
          },
        },
        required: ['theme', 'evidenceCount', 'confidence', 'summary', 'jira'],
      },
    },
    required: ['keyInsight', 'recommendations', 'actionPlan', 'productIssue'],
  },
}

// ---------------------------------------------------------------------------
// Single place for everything tunable: brand theme tokens, the sentiment
// palette, model ids shown in the UI, and analysis thresholds.
// ---------------------------------------------------------------------------

/** Experience.com brand tokens, fed to antd's ConfigProvider. */
export const brand = {
  primary: '#5b4cdb',
  primaryDeep: '#4a3aa7',
  radius: 10,
  fontFamily:
    "system-ui, -apple-system, 'Segoe UI', Roboto, 'Helvetica Neue', Arial, sans-serif",
}

/**
 * Sentiment palette — the dataviz skill's reserved *status* palette.
 *
 * Validated with scripts/validate_palette.js against a #ffffff surface:
 *   CVD separation      PASS  worst adjacent ΔE 11.3 (protan), 24.4 (tritan)
 *   Normal-vision floor PASS  worst adjacent ΔE 27.6
 *   Contrast            amber is sub-3:1 on white *by design* for status colors.
 *
 * The documented mitigation for that amber is icon + label: nowhere in this UI
 * does a sentiment colour carry meaning on its own. Every bar, arc and line
 * ships a visible written label beside it.
 */
export const sentimentColors = {
  positive: '#0ca30c',
  neutral: '#fab219',
  negative: '#d03b3b',
}

export const sentimentLabels = {
  positive: 'Positive',
  neutral: 'Neutral',
  negative: 'Negative',
}

/** Chart chrome, from the same reference palette. */
export const ink = {
  primary: '#0b0b0b',
  secondary: '#52514e',
  muted: '#898781',
  grid: '#e1e0d9',
  axis: '#c3c2b7',
  surface: '#ffffff',
  plane: '#f5f6f8',
}

/** Shown in the UI so the routing decision is visible, not just claimed. */
export const models = {
  classify: { id: 'claude-haiku-4-5-20251001', label: 'Haiku 4.5' },
  plan: { id: 'claude-sonnet-5', label: 'Sonnet 5' },
  opus: { id: 'claude-opus-5', label: 'Opus 5' },
}

export const thresholds = {
  /** Below this confidence the product issue is shown as a weak signal. */
  productIssueConfidence: 70,
  /** Themes under this share of feedback are folded out of the headline bars. */
  minThemeShare: 0.02,
}

export const account = {
  name: 'Ashwani',
  team: 'CORE UI Team',
  org: 'experience.com',
}

// ---------------------------------------------------------------------------
// Turning the model's per-response labels into the numbers the panel renders.
//
// This is deliberately plain arithmetic, not a model call. Counting is not a
// language task — asking an LLM to total up percentages is slower, costlier and
// less reliable than doing it here. The model labels; the code counts.
// ---------------------------------------------------------------------------

import { thresholds } from '../config.js'

const SENTIMENTS = ['positive', 'neutral', 'negative']

/**
 * @param {Array<{id,sentiment,themes:Array<{name,sentiment}>}>} classifications
 * @param {Array<{id,date,text,role,source,rating}>} responses
 */
export function aggregate(classifications, responses) {
  const byId = new Map(responses.map((r) => [r.id, r]))
  const rows = classifications.filter((c) => byId.has(c.id))
  const total = rows.length || 1

  // --- overall sentiment split -------------------------------------------
  const counts = { positive: 0, neutral: 0, negative: 0 }
  for (const c of rows) counts[c.sentiment] = (counts[c.sentiment] ?? 0) + 1

  const sentiment = {}
  for (const s of SENTIMENTS) sentiment[s] = Math.round((counts[s] / total) * 100)
  // Percentages must total 100 for the donut to read honestly.
  const drift = 100 - SENTIMENTS.reduce((a, s) => a + sentiment[s], 0)
  if (drift !== 0) {
    const biggest = SENTIMENTS.reduce((a, b) => (counts[a] >= counts[b] ? a : b))
    sentiment[biggest] += drift
  }

  // --- themes -------------------------------------------------------------
  const themeMap = new Map()
  for (const c of rows) {
    for (const t of c.themes ?? []) {
      if (!themeMap.has(t.name)) {
        themeMap.set(t.name, { name: t.name, count: 0, positive: 0, neutral: 0, negative: 0 })
      }
      const entry = themeMap.get(t.name)
      entry.count += 1
      entry[t.sentiment] += 1
    }
  }

  const themes = [...themeMap.values()]
    .map((t) => ({
      ...t,
      share: Math.round((t.count / total) * 100),
      // A theme's headline sentiment is whichever tone dominates its mentions.
      sentiment: SENTIMENTS.reduce((a, b) => (t[a] >= t[b] ? a : b)),
    }))
    .filter((t) => t.count / total >= thresholds.minThemeShare)
    .sort((a, b) => b.count - a.count)

  // --- daily trend --------------------------------------------------------
  const days = new Map()
  for (const c of rows) {
    const date = byId.get(c.id).date
    if (!days.has(date)) days.set(date, { date, positive: 0, neutral: 0, negative: 0, total: 0 })
    const d = days.get(date)
    d[c.sentiment] += 1
    d.total += 1
  }
  const trend = [...days.values()]
    .sort((a, b) => a.date.localeCompare(b.date))
    .map((d) => ({
      date: d.date,
      positive: Math.round((d.positive / d.total) * 100),
      neutral: Math.round((d.neutral / d.total) * 100),
      negative: Math.round((d.negative / d.total) * 100),
    }))

  // --- evidence for stage 2 ----------------------------------------------
  // Only negative verbatims from the negative themes go to Sonnet. Sending all
  // 60 would cost more and bury the signal we actually want it to reason about.
  const negativeThemes = themes.filter((t) => t.sentiment === 'negative').map((t) => t.name)
  const evidence = rows
    .filter((c) => (c.themes ?? []).some((t) => t.sentiment === 'negative'))
    .slice(0, 20)
    .map((c) => ({
      id: c.id,
      themes: c.themes.filter((t) => t.sentiment === 'negative').map((t) => t.name),
      text: byId.get(c.id).text,
      role: byId.get(c.id).role,
      source: byId.get(c.id).source,
    }))

  return {
    total: rows.length,
    counts,
    sentiment,
    themes,
    trend,
    negativeThemes,
    evidence,
    byId,
    classifications: rows,
  }
}

// ---------------------------------------------------------------------------
// Offline fallback.
//
// Live demos fail on conference wifi. If the API key is missing or the call
// errors, the panel degrades to this instead of showing an error card — the
// same pipeline, the same shapes, a rule-based classifier standing in for the
// model. The UI labels it clearly as fallback so nobody mistakes it for AI
// output.
// ---------------------------------------------------------------------------

const THEME_RULES = [
  { name: 'Checkout Issues', tone: 'negative', re: /checkout|payment failed|card |cart|pay\b|upgrade (?:flow|checkout)|tax|prorat|billing date|annual commitment|monthly or annual/i },
  { name: 'Pricing Confusion', tone: 'negative', re: /pricing|plan|tier|invoice|quoted|per-seat|bundle|cost|what i'm paying|premier|pro versus/i },
  { name: 'Support', tone: 'positive', re: /support|ticket|help|resolved|sorted|onboarding call|account manager|rep\b/i },
  { name: 'Fast Service', tone: 'positive', re: /fast|quick|same-day|within the hour|response time|turnaround|responsive|minutes/i },
  { name: 'Staff Friendliness', tone: 'positive', re: /friendly|lovely|patient|kind|helpful people|staff|team is/i },
  { name: 'Reporting', tone: 'positive', re: /report|dashboard|export|analytics/i },
  { name: 'Review Campaigns', tone: 'positive', re: /review request|survey|profile page|review volume|review count|response rate|listing/i },
]

function classifyOne(r) {
  const themes = []
  for (const rule of THEME_RULES) {
    if (!rule.re.test(r.text)) continue
    // A theme's tone follows the rule's default, flipped when the response is
    // clearly unhappy about it.
    const negativeContext = r.rating <= 2 || /confus|not clear|error|fail|broken|didn't understand|couldn't|gave up|surprised|don't understand|doesn't|didn't match|needs a proper/i.test(r.text)
    const tone = rule.tone === 'negative' ? 'negative' : negativeContext && themes.length === 0 ? 'neutral' : 'positive'
    themes.push({ name: rule.name, sentiment: rule.tone === 'negative' ? 'negative' : tone })
  }

  const sentiment = r.rating >= 4 ? 'positive' : r.rating === 3 ? 'neutral' : 'negative'
  return { id: r.id, sentiment, themes }
}

export function fallbackClassify(responses) {
  return {
    classifications: responses.map(classifyOne),
    _meta: { fallback: true, model: 'rule-based fallback', ms: 0, costUsd: 0, inputTokens: 0, outputTokens: 0 },
  }
}

