async function post(url, body) {
  const res = await fetch(url, {
    method: 'POST',
    headers: { 'content-type': 'application/json' },
    body: JSON.stringify(body),
  })
  const json = await res.json()
  if (!res.ok) {
    const err = new Error(json.error || `Request failed (${res.status})`)
    err.code = json.code
    throw err
  }
  return json
}

