/**
 * The evidence layer. Clicking a theme bar filters straight to the verbatims
 * behind it — the number on the chart is never the end of the trail.
 */
export default function FeedbackList({ analysis, selectedTheme, onClearTheme }) {
  const [query, setQuery] = useState('')
  const [sentiment, setSentiment] = useState('all')

  const theme = analysis.themes.find((t) => t.name === selectedTheme)

  const rows = useMemo(() => {
    return analysis.classifications
      .map((c) => ({ ...c, ...analysis.byId.get(c.id) }))
      .filter((r) => (selectedTheme ? r.themes.some((t) => t.name === selectedTheme) : true))
      .filter((r) => (sentiment === 'all' ? true : r.sentiment === sentiment))
      .filter((r) => (query ? r.text.toLowerCase().includes(query.toLowerCase()) : true))
      .sort((a, b) => b.date.localeCompare(a.date))
  }, [analysis, selectedTheme, sentiment, query])

  return (
    <Card
      className="panel"
      variant="outlined"
      title={
        <span className="panel-title">
          {selectedTheme ? (
            <>
              <Button type="text" size="small" icon={<ArrowLeftOutlined />} onClick={onClearTheme} />
              <i className="dot" style={{ background: sentimentColors[theme?.sentiment ?? 'neutral'] }} aria-hidden="true" />
              {selectedTheme}
            </>
          ) : (
            'All feedback'
          )}
        </span>
      }
      extra={<span className="panel-extra">{rows.length} of {analysis.total} responses</span>}
    >
      {selectedTheme && theme && (
        <div className="drilldown">
          <DonutBreakdown
            counts={{ positive: theme.positive, neutral: theme.neutral, negative: theme.negative }}
            title={`${selectedTheme} sentiment breakdown`}
          />
          <div className="drilldown-note">
            <div className="issue-label">What this theme is</div>
            <p>
              {theme.count} of {analysis.total} responses mention <strong>{selectedTheme}</strong> — {theme.share}% of
              all feedback in the window. Overall it reads{' '}
              <strong>{sentimentLabels[theme.sentiment].toLowerCase()}</strong>.
            </p>
          </div>
        </div>
      )}

      <div className="filters">
        <Input
          allowClear
          prefix={<SearchOutlined />}
          placeholder="Search feedback"
          value={query}
          onChange={(e) => setQuery(e.target.value)}
          style={{ maxWidth: 280 }}
        />
        <Select
          value={sentiment}
          onChange={setSentiment}
          style={{ width: 160 }}
          options={[
            { value: 'all', label: 'All sentiment' },
            { value: 'positive', label: 'Positive' },
            { value: 'neutral', label: 'Neutral' },
            { value: 'negative', label: 'Negative' },
          ]}
        />
      </div>

      {rows.length === 0 ? (
        <Empty image={Empty.PRESENTED_IMAGE_SIMPLE} description="No matching feedback" />
      ) : (
        <ul className="feed">
          {rows.slice(0, 12).map((r) => (
            <li key={r.id} className="feed-item">
              <span className="feed-dot" style={{ background: sentimentColors[r.sentiment] }} aria-hidden="true" />
              <div className="feed-body">
                <p className="feed-text">{r.text}</p>
                <div className="feed-meta">
                  <Tag color={SENTIMENT_TAG[r.sentiment]}>{sentimentLabels[r.sentiment]}</Tag>
                  {r.themes.map((t) => (
                    <Tag key={t.name} bordered={false}>
                      {t.name}
                    </Tag>
                  ))}
                  <span className="feed-src">
                    {r.role} · {r.source} · {r.date}
                  </span>
                </div>
              </div>
            </li>
          ))}
        </ul>
      )}

      {rows.length > 12 && <div className="feed-more">Showing 12 of {rows.length} matching responses</div>}
    </Card>
  )
}

import { Card, Table, Tag, Tooltip } from 'antd'
import { NodeIndexOutlined, InfoCircleOutlined } from '@ant-design/icons'
import { models } from '../config.js'
import { PRICES, OPUS_MODEL } from '../../server/models.js'

const usd = (n) => (n < 0.01 ? `$${n.toFixed(4)}` : `$${n.toFixed(3)}`)

/**
 * Rule 2 of the brief is scored, so the routing decision is shown rather than
 * merely claimed: which model ran which stage, what it cost, and what the naive
 * everything-on-Opus run would have cost instead.
 */
export default function ModelRouter({ classifyMeta, planMeta }) {
  const stages = [
    classifyMeta && {
      key: 'classify',
      stage: 'Classify 60 verbatims',
      model: classifyMeta.fallback ? 'Rule-based fallback' : models.classify.label,
      why: 'Labelling against a fixed schema. High volume, no hard reasoning.',
      meta: classifyMeta,
    },
    planMeta && {
      key: 'plan',
      stage: 'Action plan + Jira ticket',
      model: planMeta.fallback ? 'Bundled fallback' : models.plan.label,
      why: 'Impact-vs-effort judgement and ticket authoring. Reasoning earns its cost here.',
      meta: planMeta,
    },
  ].filter(Boolean)

  if (!stages.length) return null

  const spent = stages.reduce((a, s) => a + (s.meta.costUsd ?? 0), 0)
  const tokensIn = stages.reduce((a, s) => a + (s.meta.inputTokens ?? 0), 0)
  const tokensOut = stages.reduce((a, s) => a + (s.meta.outputTokens ?? 0), 0)
  const opus = PRICES[OPUS_MODEL]
  const opusCost = (tokensIn / 1e6) * opus.in + (tokensOut / 1e6) * opus.out
  const live = stages.some((s) => !s.meta.fallback)

  const columns = [
    { title: 'Stage', dataIndex: 'stage' },
    {
      title: 'Model',
      dataIndex: 'model',
      render: (v, r) => <Tag color={r.meta.fallback ? 'default' : 'purple'}>{v}</Tag>,
    },
    { title: 'Why this model', dataIndex: 'why', className: 'router-why' },
    {
      title: 'Latency',
      dataIndex: 'ms',
      width: 100,
      render: (_, r) => (r.meta.ms ? `${(r.meta.ms / 1000).toFixed(1)}s` : '—'),
    },
    {
      title: 'Cost',
      dataIndex: 'cost',
      width: 100,
      render: (_, r) => (r.meta.costUsd ? usd(r.meta.costUsd) : '—'),
    },
  ]

  return (
    <Card
      className="panel router"
      variant="outlined"
      title={
        <span className="panel-title">
          <NodeIndexOutlined /> Model routing
        </span>
      }
      extra={
        <Tag color={live ? 'purple' : 'default'}>{live ? 'Live API' : 'Offline fallback'}</Tag>
      }
    >
      <Table rowKey="key" size="small" pagination={false} columns={columns} dataSource={stages} />

      {live && (
        <div className="router-foot">
          <div>
            <span className="router-foot-label">This run</span>
            <span className="router-foot-value">{usd(spent)}</span>
          </div>
          <div>
            <span className="router-foot-label">
              Same run on Opus{' '}
              <Tooltip title="Identical token counts priced at Opus list rates — the cost of not routing.">
                <InfoCircleOutlined />
              </Tooltip>
            </span>
            <span className="router-foot-value muted">{usd(opusCost)}</span>
          </div>
          <div>
            <span className="router-foot-label">Saved by routing</span>
            <span className="router-foot-value good">
              {opusCost > 0 ? `${Math.round((1 - spent / opusCost) * 100)}%` : '—'}
            </span>
          </div>
        </div>
      )}
    </Card>
  )
}

import { useEffect, useMemo, useState } from 'react'
import { Alert, Button, Card, Col, Layout, Modal, Row, Select, Tag, Input, App as AntApp } from 'antd'
import { ThunderboltOutlined, UploadOutlined, LineChartOutlined, TagsOutlined } from '@ant-design/icons'

import Sidebar from './components/Sidebar.jsx'
import StatTiles from './components/StatTiles.jsx'
import SentimentTrend from './components/SentimentTrend.jsx'
import TopThemes from './components/TopThemes.jsx'
import RecommendationRail from './components/RecommendationRail.jsx'
import ActionPlan from './components/ActionPlan.jsx'
import ProductIssueCard from './components/ProductIssueCard.jsx'
import FeedbackList from './components/FeedbackList.jsx'
import ModelRouter from './components/ModelRouter.jsx'

import sample from './data/feedback.sample.json'
import { aggregate } from './lib/aggregate.js'
import { classify, actionPlan as fetchPlan, checkHealth } from './lib/api.js'

export default function App() {
  const { message } = AntApp.useApp()

  const [responses, setResponses] = useState(sample.responses)
  const [classification, setClassification] = useState(null)
  const [plan, setPlan] = useState(null)
  const [analyzing, setAnalyzing] = useState(false)
  const [planning, setPlanning] = useState(false)
  const [selectedTheme, setSelectedTheme] = useState(null)
  const [health, setHealth] = useState(null)
  const [uploadOpen, setUploadOpen] = useState(false)
  const [uploadText, setUploadText] = useState('')
  const [notice, setNotice] = useState(null)

  useEffect(() => {
    checkHealth().then(setHealth)
  }, [])

  const analysis = useMemo(
    () => (classification ? aggregate(classification.classifications, responses) : null),
    [classification, responses],
  )

  const runAnalysis = async () => {
    setAnalyzing(true)
    setPlan(null)
    setSelectedTheme(null)
    setNotice(null)
    try {
      const result = await classify(responses)
      setClassification(result)
      if (result._fallbackReason) {
        setNotice(
          `Live model call unavailable (${result._fallbackReason}). Showing the rule-based fallback so the panel still runs.`,
        )
      } else {
        message.success(`Classified ${result.classifications.length} responses`)
      }
    } finally {
      setAnalyzing(false)
    }
  }

  const runPlan = async () => {
    if (!analysis) return
    setPlanning(true)
    try {
      const summary = {
        totalResponses: analysis.total,
        sentimentSplit: analysis.sentiment,
        themes: analysis.themes.map((t) => ({
          name: t.name,
          count: t.count,
          share: t.share,
          positive: t.positive,
          neutral: t.neutral,
          negative: t.negative,
        })),
      }
      const result = await fetchPlan(summary, analysis.evidence)
      setPlan(result)
      if (result._fallbackReason) {
        setNotice(`Action plan generated from the bundled fallback (${result._fallbackReason}).`)
      } else {
        message.success('Action plan generated')
      }
    } finally {
      setPlanning(false)
    }
  }

  const applyUpload = () => {
    const text = uploadText.trim()
    if (!text) return
    let parsed
    try {
      const json = JSON.parse(text)
      const arr = Array.isArray(json) ? json : json.responses
      parsed = arr.map((r, i) => ({
        id: r.id ?? `UP-${i + 1}`,
        date: r.date ?? new Date().toISOString().slice(0, 10),
        source: r.source ?? 'Uploaded',
        role: r.role ?? 'Customer',
        rating: r.rating ?? 3,
        text: r.text ?? String(r),
      }))
    } catch {
      // Not JSON — treat it as one comment per line.
      parsed = text
        .split('\n')
        .map((l) => l.trim())
        .filter(Boolean)
        .map((line, i) => ({
          id: `UP-${i + 1}`,
          date: new Date().toISOString().slice(0, 10),
          source: 'Uploaded',
          role: 'Customer',
          rating: 3,
          text: line,
        }))
    }

    if (!parsed.length) {
      message.error('Nothing to import')
      return
    }
    setResponses(parsed)
    setClassification(null)
    setPlan(null)
    setUploadOpen(false)
    setUploadText('')
    message.success(`Loaded ${parsed.length} responses — run Analyze feedback`)
  }

  const resetToSample = () => {
    setResponses(sample.responses)
    setClassification(null)
    setPlan(null)
    message.info('Sample dataset restored')
  }

  return (
    <Layout className="shell">
      <Sidebar total={responses.length} />

      <Layout>
        <Layout.Header className="topbar">
          <div>
            <h1 className="page-title">
              Feedback Insights <Tag color="purple" className="ai-tag">AI powered</Tag>
            </h1>
            <p className="page-sub">
              Understand what your customers are saying — and turn it into something a team can act on.
            </p>
          </div>

          <div className="topbar-actions">
            <Select
              defaultValue="30"
              style={{ width: 148 }}
              options={[
                { value: '30', label: 'Last 30 days' },
                { value: '7', label: 'Last 7 days' },
                { value: '90', label: 'Last 90 days' },
              ]}
            />
            <Button icon={<UploadOutlined />} onClick={() => setUploadOpen(true)}>
              Upload feedback
            </Button>
            <Button type="primary" icon={<ThunderboltOutlined />} loading={analyzing} onClick={runAnalysis}>
              Analyze feedback
            </Button>
          </div>
        </Layout.Header>

        <Layout.Content className="content">
          {notice && (
            <Alert type="info" showIcon closable className="notice" message={notice} onClose={() => setNotice(null)} />
          )}

          {health && !health.liveMode && !classification && (
            <Alert
              type="warning"
              showIcon
              className="notice"
              message="No ANTHROPIC_API_KEY found"
              description="The panel runs on its rule-based fallback. Add a key to .env and restart to route the real Haiku and Sonnet calls."
            />
          )}

          {!analysis ? (
            <Card className="empty-state" variant="outlined">
              <h2>{responses.length} feedback responses, unread</h2>
              <p>
                NPS scores, in-app surveys and support tickets from loan officers, agents and branch managers using
                Experience.com. Somebody has to read all of it, spot the patterns, and decide what needs fixing.
              </p>
              <p className="empty-cta">
                <Button type="primary" size="large" icon={<ThunderboltOutlined />} loading={analyzing} onClick={runAnalysis}>
                  Analyze feedback
                </Button>
              </p>
              <ul className="empty-preview">
                {responses.slice(0, 6).map((r) => (
                  <li key={r.id}>“{r.text}”</li>
                ))}
              </ul>
            </Card>
          ) : (
            <>
              <StatTiles analysis={analysis} plan={plan} />

              <Row gutter={[16, 16]} className="row">
                <Col xs={24} xl={16}>
                  <Card
                    className="panel"
                    variant="outlined"
                    title={<span className="panel-title"><LineChartOutlined /> Sentiment trend</span>}
                    extra={<span className="panel-extra">{sample.window.from} → {sample.window.to}</span>}
                  >
                    <SentimentTrend trend={analysis.trend} />
                  </Card>

                  <Card
                    className="panel"
                    variant="outlined"
                    title={<span className="panel-title"><TagsOutlined /> Top themes</span>}
                    extra={<span className="panel-extra">Share of all feedback · click to drill in</span>}
                  >
                    <TopThemes themes={analysis.themes} onSelect={setSelectedTheme} selected={selectedTheme} />
                  </Card>
                </Col>

                <Col xs={24} xl={8}>
                  <RecommendationRail
                    plan={plan}
                    insight={plan?.keyInsight}
                    loading={planning && !plan}
                    planLoading={planning}
                    hasPlan={Boolean(plan)}
                    onGeneratePlan={runPlan}
                  />
                </Col>
              </Row>

              {plan && (
                <Row gutter={[16, 16]} className="row">
                  <Col xs={24} xl={14}>
                    <ActionPlan plan={plan} total={analysis.total} />
                  </Col>
                  <Col xs={24} xl={10}>
                    <ProductIssueCard issue={plan.productIssue} />
                  </Col>
                </Row>
              )}

              <ModelRouter classifyMeta={classification?._meta} planMeta={plan?._meta} />

              <FeedbackList
                analysis={analysis}
                selectedTheme={selectedTheme}
                onClearTheme={() => setSelectedTheme(null)}
              />

              <div className="reset-row">
                <Button type="link" onClick={resetToSample}>
                  Restore sample dataset
                </Button>
              </div>
            </>
          )}
        </Layout.Content>
      </Layout>

      <Modal
        open={uploadOpen}
        title="Upload feedback"
        onCancel={() => setUploadOpen(false)}
        onOk={applyUpload}
        okText="Load responses"
        width={640}
      >
        <p className="upload-help">
          Paste a JSON array of responses, or one comment per line. Anything you paste replaces the sample dataset.
        </p>
        <Input.TextArea
          rows={12}
          value={uploadText}
          onChange={(e) => setUploadText(e.target.value)}
          placeholder={'Support was great but pricing was confusing...\nCheckout kept failing on my card.\n\nor: [{"id":"1","text":"...","rating":2}]'}
        />
      </Modal>
    </Layout>
  )
}

