.feed-more { margin-top: 12px; font-size: 12.5px; color: var(--ink-3); text-align: center; }

.reset-row { text-align: center; }
.upload-help { color: var(--ink-2); font-size: 13px; margin-top: 0; }

@media (max-width: 900px) {
