#!/usr/bin/env python3
"""
Build ai-chat-export.json / .txt from the live Claude Code session transcript.

This harness has no client-side `/export` slash command available to the agent,
so the export is assembled directly from the on-disk session JSONL — the same
source `/export` reads. Nothing is invented or reconstructed from memory.

Two things are deliberately transformed:
  1. Secrets are redacted. The live ANTHROPIC_API_KEY appears in the transcript
     because it was pasted into a file; it must never reach a shared repo.
  2. Base64 image blobs are replaced with a short placeholder. They are
     megabytes each, carry no evaluable signal, and would bloat the branch.
"""
import json
import re
import sys
from pathlib import Path

SRC = Path(
    "/Users/ashwanidohray/.claude/projects/"
    "-Users-ashwanidohray-Github2026-hackathon2026/"
    "407ff647-970e-439a-8dc2-aff5433a9971.jsonl"
)
OUT_DIR = Path("/Users/ashwanidohray/Github2026/hackathon2026")

SECRET_RE = re.compile(r"sk-ant-[A-Za-z0-9_\-]{20,}")
REDACTED = "sk-ant-REDACTED"


def scrub(text):
    if not isinstance(text, str):
        return text
    return SECRET_RE.sub(REDACTED, text)


def render_content(content):
    """Flatten a message's content blocks into readable parts."""
    if isinstance(content, str):
        return [{"type": "text", "text": scrub(content)}]

    parts = []
    for block in content or []:
        if not isinstance(block, dict):
            continue
        btype = block.get("type")

        if btype == "text":
            parts.append({"type": "text", "text": scrub(block.get("text", ""))})

        elif btype == "thinking":
            parts.append({"type": "thinking", "text": scrub(block.get("thinking", ""))})

        elif btype == "tool_use":
            parts.append({
                "type": "tool_use",
                "name": block.get("name"),
                "input": json.loads(scrub(json.dumps(block.get("input", {})))),
            })

        elif btype == "tool_result":
            inner = block.get("content")
            if isinstance(inner, list):
                texts = []
                for c in inner:
                    if isinstance(c, dict) and c.get("type") == "text":
                        texts.append(c.get("text", ""))
                    elif isinstance(c, dict) and c.get("type") == "image":
                        texts.append("[image omitted from export]")
                inner = "\n".join(texts)
            parts.append({
                "type": "tool_result",
                "is_error": bool(block.get("is_error")),
                "text": scrub(inner if isinstance(inner, str) else json.dumps(inner))[:20000],
            })

        elif btype == "image":
            parts.append({"type": "image", "text": "[image omitted from export]"})

    return parts


def main():
    if not SRC.exists():
        sys.exit(f"transcript not found: {SRC}")

    messages = []
    with SRC.open() as fh:
        for line in fh:
            try:
                rec = json.loads(line)
            except json.JSONDecodeError:
                continue

            if rec.get("type") not in ("user", "assistant"):
                continue

            msg = rec.get("message") or {}
            role = msg.get("role") or rec.get("type")
            parts = render_content(msg.get("content"))
            if not parts:
                continue

            messages.append({
                "index": len(messages) + 1,
                "role": role,
                "timestamp": rec.get("timestamp"),
                "model": msg.get("model"),
                "content": parts,
            })

    export = {
        "tool": "Claude Code",
        "model": "claude-opus-5[1m]",
        "session_id": "407ff647-970e-439a-8dc2-aff5433a9971",
        "project": "Feedback Insights — AI Feedback-to-Action Assistant",
        "author": "Ashwani — Senior Software Engineer, CORE UI",
        "hackathon": "Experience.com AI Hackathon, 26 August 2026",
        "export_note": (
            "Assembled directly from the on-disk Claude Code session transcript "
            "(the same source /export reads); this harness exposes no /export "
            "slash command to the agent. Live API keys are redacted and base64 "
            "image blobs are replaced with placeholders — nothing else is altered."
        ),
        "message_count": len(messages),
        "messages": messages,
    }

    js = json.dumps(export, indent=2, ensure_ascii=False)
    leaked = SECRET_RE.findall(js)
    leaked = [s for s in leaked if s != REDACTED]
    if leaked:
        sys.exit(f"ABORT: {len(leaked)} unredacted secrets still present")

    (OUT_DIR / "ai-chat-export.json").write_text(js)

    # Readable plain-text twin.
    lines = [
        "Claude Code session export — Feedback Insights",
        "Ashwani — Senior Software Engineer, CORE UI",
        "Experience.com AI Hackathon, 26 August 2026",
        f"{len(messages)} messages",
        "=" * 72,
        "",
    ]
    for m in messages:
        lines.append(f"--- [{m['index']}] {m['role'].upper()}  {m.get('timestamp') or ''} ---")
        for p in m["content"]:
            if p["type"] == "text":
                lines.append(p["text"])
            elif p["type"] == "thinking":
                lines.append(f"(thinking) {p['text']}")
            elif p["type"] == "tool_use":
                lines.append(f"[tool: {p['name']}]")
                lines.append(json.dumps(p["input"], indent=2, ensure_ascii=False)[:4000])
            elif p["type"] == "tool_result":
                tag = "tool result (error)" if p["is_error"] else "tool result"
                lines.append(f"[{tag}] {p['text'][:4000]}")
            else:
                lines.append(p.get("text", ""))
        lines.append("")

    (OUT_DIR / "ai-chat-export.txt").write_text("\n".join(lines))

    print(f"messages: {len(messages)}")
    print(f"json: {(OUT_DIR / 'ai-chat-export.json').stat().st_size / 1024:.0f} KB")
    print(f"txt:  {(OUT_DIR / 'ai-chat-export.txt').stat().st_size / 1024:.0f} KB")
    print("secrets redacted:", js.count(REDACTED))


if __name__ == "__main__":
    main()
